INSERT INTO `tx_t3gamingrecords_domain_model_game` (`uid`, `pid`, `tstamp`, `crdate`, `deleted`, `hidden`, `title`, `description`, `date_release`, `difficulties`, `levels`, `platform_id`, `publisher_id`, `slug`, `fal_media`, `starttime`, `endtime`, `sys_language_uid`, `l10n_parent`, `l10n_source`, `l10n_state`) VALUES
(1, 4, 1781645710, 1778690355, 0, 0, 'Golden Eye 007', '<p>GoldenEye 007 is a 1997 first-person shooter developed by Rare and published by Nintendo for the Nintendo 64. &nbsp;Based on the 1995 James Bond film GoldenEye, it follows agent James Bond as he thwarts a criminal syndicate\'s plan to use the EMP satellite weapon \"<i>GoldenEye</i>.\" The game features a single-player campaign with 20 levels across 9 missions and two bonus levels, emphasizing stealth, varied objectives, and realistic weapon mechanics.</p>\r\n<p>Directed by Martin Hollis, the game was a critical and commercial success, selling over 8 million copies and becoming the third-best-selling N64 title. &nbsp;It was praised for its groundbreaking split-screen multiplayer mode (supporting up to four players), atmospheric single-player missions, and innovative features like stealth elements and widescreen support. &nbsp;It received multiple awards, including a BAFTA Interactive Entertainment Award in 1998, and is considered one of the most influential video games ever made.</p>', 800661600, 0, 0, 1, 1, 'golden-eye-007', 1, 0, 0, 0, 0, 0, NULL),
(2, 4, 1778968154, 1778705301, 0, 0, 'Mario Kart 64', '', 0, 4, 0, 1, 0, 'mario-kart-64', 0, 0, 0, 0, 0, 0, NULL),
(3, 4, 1778968501, 1778706941, 0, 0, 'Super Mario 64', '', 0, 0, 0, 1, 0, 'super-mario-64', 0, 0, 0, 0, 0, 0, NULL),
(4, 4, 1779394472, 1778728171, 0, 0, 'Baloon Fight', '<p><strong>Balloon Fight GB (2000)</strong>: A <strong>Game Boy Color</strong> exclusive remake of Balloon Kid released in Japan on <strong>July 31, 2000</strong>. &nbsp;Developed by <strong>Pax Softnica</strong>, this version added <strong>color graphics</strong>, <strong>battery-backed save data</strong>, and a map screen for level selection.</p>', 964994400, 1, 8, 2, 0, 'baloon-fight', 1, 0, 0, 0, 0, 0, NULL);
